          ...(submittedAt === undefined ? {} : { addressedAcceptanceIds: ['A1'] }),
          acceptanceReview: fixtureAcceptanceReview(['A1']),
          checks: [],
          knownLimits: [],
          ...(submittedAt === undefined ? {} : { submittedAt }),
        },
