    const reads = vi.spyOn(fs, 'open');
    const fields = ['phase', 'workflow', 'build_mode', 'tdd_mode', 'review_mode', 'plan'];
    const result = await cli(fields);
    expect(result.exitCode, result.stdout).toBe(0);
    const output = JSON.parse(result.stdout!);
    expect(output.data).toEqual({
      change: 'demo',
      fields: {
        phase: 'open',
        workflow: 'tweak',
        build_mode: 'direct',
        tdd_mode: 'direct',
        review_mode: 'off',
        plan: 'null',
      },
    });
    expect(output.stdout).toBe(
      'phase=open\nworkflow=tweak\nbuild_mode=direct\ntdd_mode=direct\nreview_mode=off\nplan=null\n',
    );
    expect(reads.mock.calls.filter(([file]) => String(file) === stateFile)).toHaveLength(1);
    expect(JSON.parse((await cli(['phase'])).stdout!).stdout).toBe('open\n');
    expect((await cli(['phase', 'phase'])).exitCode).toBe(1);
    expect((await cli(['phase', '--unknown'])).exitCode).toBe(1);
  });

  it('returns SDK entry and recovery continuation from the same inspected Run', async () => {
    const { root, stateFile, store } = await preparedChange();
    const before = (await store.read('demo'))!;
    const expected = {
      kind: 'action',
      stepId: 'tweak.open',
      actionId: before.actions[0].id,
      attempt: before.actions[0].attempt,
      inputHash: before.actions[0].inputHash,
      ref: before.actions[0].ref,
    };
    const reads = vi.spyOn(fs, 'open');
    for (const suffix of [[], ['--recover']]) {
      reads.mockClear();
      const result = await runClassicCli(
        ['state', 'check', 'demo', 'open', ...suffix, '--json'],
        undefined,
        { projectRoot: root, invocationCwd: root },
      );
      expect(result.exitCode, result.stdout).toBe(0);
      expect(JSON.parse(result.stdout!).data).toMatchObject({
        run: { id: before.runId, revision: before.revision },
        nextAction: expected,
      });
      expect(reads.mock.calls.filter(([file]) => String(file) === stateFile)).toHaveLength(1);
    }
  });

  it('prioritizes reconciliation over another pending Action without mutating the Run', async () => {
    const { store } = await preparedChange();
    const run = (await store.read('demo'))!;
    const pending = run.actions[0];
    const unresolved = { ...pending, id: 'interrupted', status: 'unknown' as const };
    const observed = { ...run, actions: [pending, unresolved] };
    expect(classicSdkNextAction(observed)).toMatchObject({
      kind: 'reconcile',
      actionId: 'interrupted',
    });
    expect(observed.actions).toEqual([pending, unresolved]);
    expect(classicSdkNextAction({ ...observed, status: 'completed' })).toEqual({ kind: 'done' });
  });

  it('reads stable state once without rewriting either projection', async () => {
    const { store, stateFile, markerFile } = await preparedChange();
    const before = await store.read('demo');
    const timestamp = new Date('2020-01-01T00:00:00.000Z');
    await fs.utimes(stateFile, timestamp, timestamp);
    await fs.utimes(markerFile, timestamp, timestamp);
    const reads = vi.spyOn(fs, 'open');
    const renames = vi.spyOn(fs, 'rename');
    expect(await store.read('demo')).toEqual(before);
    expect(reads.mock.calls.filter(([file]) => String(file) === stateFile)).toHaveLength(1);
    expect(renames.mock.calls.filter(([, target]) => String(target) === markerFile)).toHaveLength(
      0,
    );
    expect((await fs.stat(stateFile)).mtimeMs).toBe(timestamp.getTime());
    expect((await fs.stat(markerFile)).mtimeMs).toBe(timestamp.getTime());
  });

  it('does not probe Git while projecting a Run that has no branch binding', async () => {
    const { store } = await preparedChange({ profile: 'full' });
    const { result, metrics } = await withCometRuntimeMetrics(() => store.read('demo'));
    expect(result?.state).toMatchObject({ isolation: null, boundBranch: null });
    expect(metrics.gitCommands).toBe(0);
  });

  it('skips projection-only branch probes while entry checks still reject branch drift', async () => {
    const { root, store, stateFile } = await preparedChange({ git: true, isolation: 'current' });
    const before = (await store.read('demo'))!;
    expect(before.state).toMatchObject({ isolation: 'current', boundBranch: 'main' });
    const stable = await withCometRuntimeMetrics(() => store.read('demo'));
    expect(stable.result).toEqual(before);
    expect(stable.metrics.gitCommands).toBe(0);

    execFileSync('git', ['symbolic-ref', 'HEAD', 'refs/heads/other'], { cwd: root });
    const drifted = await withCometRuntimeMetrics(() => store.read('demo'));
    expect(drifted.result).toEqual(before);
    expect(drifted.metrics.gitCommands).toBe(0);
    const reads = vi.spyOn(fs, 'open');
    const checked = await withClassicCommandContext(
      { projectRoot: root, invocationCwd: root },
      () => runClassicCli(['state', 'check', 'demo', 'open', '--json']),
    );
    expect(checked.exitCode).toBe(1);
    expect(JSON.stringify(JSON.parse(checked.stdout!).data)).toMatch(
      /bound to branch.*main.*other/u,
    );
    expect(reads.mock.calls.filter(([file]) => String(file) === stateFile)).toHaveLength(1);
    expect(await store.read('demo')).toEqual(before);
  });

  it('imports user settings once, advances its marker, and still rejects Runtime-owned edits', async () => {
    const { store, stateFile, markerFile } = await preparedChange();
    const before = (await store.read('demo'))!;
    const source = await fs.readFile(stateFile, 'utf8');
    await fs.writeFile(stateFile, source.replace(/^language: en$/mu, 'language: zh-CN'));
    const renames = vi.spyOn(fs, 'rename');
    const imported = (await store.read('demo'))!;
    expect(imported.revision).toBe(before.revision + 1);
    expect(imported.state).toMatchObject({ language: 'zh-CN' });
    expect(renames.mock.calls.filter(([, target]) => String(target) === markerFile)).toHaveLength(
      1,
    );
    expect(JSON.parse(await fs.readFile(markerFile, 'utf8')).revision).toBe(imported.revision);
    renames.mockClear();
    expect((await store.read('demo'))?.revision).toBe(imported.revision);
    expect(renames.mock.calls.filter(([, target]) => String(target) === markerFile)).toHaveLength(
      0,
    );
    await fs.writeFile(
      stateFile,
      (await fs.readFile(stateFile, 'utf8')).replace(/^phase: .*$/mu, 'phase: archive'),
    );
    await expect(store.read('demo')).rejects.toThrow(/Runtime-owned field/u);
  });

  it('rejects a stale CAS and repairs a missing marker without changing revision', async () => {
    const { store, markerFile } = await preparedChange();
    const before = (await store.read('demo'))!;
    expect(
      await store.compareAndSwap('demo', before.revision + 1, {
        ...before,
        revision: before.revision + 2,
      }),
    ).toBe(false);
    await fs.rm(markerFile);
    expect((await store.read('demo'))?.revision).toBe(before.revision);
    expect(JSON.parse(await fs.readFile(markerFile, 'utf8')).revision).toBe(before.revision);
  });

  it.skipIf(process.platform === 'win32')(
    'rejects an equal-content projection marker replaced by a symlink',
    async () => {
      const { root, store, markerFile } = await preparedChange();
      await store.read('demo');
      const target = path.join(root, 'copied-marker.json');
      const source = await fs.readFile(markerFile, 'utf8');
      await fs.writeFile(target, source);
      await fs.rm(markerFile);
      await fs.symlink(target, markerFile);
      await expect(store.read('demo')).rejects.toThrow(/symbolic link/u);
      expect(await fs.readFile(target, 'utf8')).toBe(source);
    },
  );
});

import { describe, expect, it } from 'vitest';
import {
  assignClassicTaskIds,
  classicTaskRequirements,
  completeClassicTask,
  inspectClassicPlanTasks,
  parseClassicTasks,
  synchronizeClassicPlanTasks,
  validateClassicTaskPlan,
} from '../../../domains/comet-classic/classic-tasks.js';

describe('Classic canonical tasks', () => {
  it('synchronizes mapped legacy checkboxes by ID, never by order or task wording', () => {
    const tasks = parseClassicTasks(
      '- [x] renamed <!-- comet-task:a -->\n- [ ] second <!-- comet-task:b -->',
    );
    const plan = '- [x] second <!-- comet-task:b -->\n- [ ] old name <!-- comet-task:a -->\n';
    expect(inspectClassicPlanTasks(plan, tasks).unmapped).toEqual([]);
    const updated = synchronizeClassicPlanTasks(plan, tasks);
    expect(parseClassicTasks(updated).map((task) => [task.id, task.completed])).toEqual([
      ['b', false],
      ['a', true],
    ]);
    expect(synchronizeClassicPlanTasks(updated, tasks)).toBe(updated);
  });
  it('preserves and reports unmapped or extra legacy plan tasks instead of guessing completion', () => {
    const tasks = parseClassicTasks('- [x] done <!-- comet-task:a -->');
    const plan = '- [ ] done\n- [ ] extra <!-- comet-task:other -->';
    expect(inspectClassicPlanTasks(plan, tasks).unmapped).toHaveLength(2);
    expect(() => synchronizeClassicPlanTasks(plan, tasks)).toThrow('mapping');
    expect(synchronizeClassicPlanTasks('Plan references only', tasks)).toBe('Plan references only');
  });
  it('uses canonical plan references without a second progress ledger and preserves legacy plans', () => {
    const tasks = parseClassicTasks('- [ ] one <!-- comet-task:a -->');
    const plan =
      '<!-- comet-task-authority: openspec/changes/demo/tasks.md -->\n## Implementation\n<!-- comet-task-ref:a -->\nImplementation details';
    const validate = (text: string) =>
      validateClassicTaskPlan(text, 'openspec/changes/demo/tasks.md', tasks);
    expect(validate(plan)).toBe('canonical');
    expect(validate('- [ ] legacy')).toBe('legacy');
    expect(() => validate(plan + '\n- [x] duplicate ledger')).toThrow('second checkbox');
    expect(() => validate(plan.replace('ref:a', 'ref:b'))).toThrow('missing task');
    expect(() => validate(plan.replace('<!-- comet-task-ref:a -->', ''))).toThrow('each task');
    expect(() => validate(plan.replace('/demo/', '/other/'))).toThrow('this change');
  });
  it('ignores fenced examples and recognizes nested tasks and either bullet', () => {
    expect(parseClassicTasks('```md\n- [x] example\n```\n- [ ] parent\n  * [X] child\n')).toEqual([
      { id: null, text: 'parent', completed: false, line: 4 },
      { id: null, text: 'child', completed: true, line: 5 },
    ]);
  });
  it.each(['\n', '\r\n'])('preserves line endings %j and assigns persistent unique IDs', (eol) => {
    const source = `- [ ] same${eol}- [x] same${eol}`;
    const assigned = assignClassicTaskIds(source);
    const tasks = parseClassicTasks(assigned);
    expect(tasks[0].id).toBeTruthy();
    expect(tasks[1].id).not.toBe(tasks[0].id);
    expect(assignClassicTaskIds(assigned)).toBe(assigned);
    expect(assigned.split(eol)).toHaveLength(3);
  });
  it.each(['\n', '\r\n'])(
    'ignores task IDs for preset scope while preserving examples and task text (%j)',
    (eol) => {
      const source = [
        '# Tasks',
        '```md',
        '- [x] example',
        '```',
        '- [ ] first',
        '  * [ ] second',
        '',
      ].join(eol);
      const assigned = assignClassicTaskIds(source);
      const tasks = parseClassicTasks(assigned);
      const completed = completeClassicTask(assigned, tasks[0].id!, 'legacy-task-revision');
      const scope = (text: string) => classicTaskRequirements(text, { taskIds: 'ignore' });
      expect(scope(completed)).toBe(scope(source));
      expect(scope(completed.replace('first', 'different scope'))).not.toBe(scope(source));
      expect(scope(completed.replace('- [x] example', '- [ ] example'))).not.toBe(scope(source));
    },
  );
  it('completes the current task by ID after reorder or an Agent-accepted description edit', () => {
    const source = '- [ ] one <!-- comet-task:a -->\n- [ ] two <!-- comet-task:b -->\n';
    const reordered = source.split('\n').slice(0, 2).reverse().join('\n') + '\n';
    const result = completeClassicTask(reordered, 'a', 'legacy-task-revision');
    expect(parseClassicTasks(result).map((task) => [task.id, task.completed])).toEqual([
      ['b', false],
      ['a', true],
    ]);
    expect(
      completeClassicTask(source.replace('one', 'changed'), 'a', 'legacy-task-revision'),
    ).toContain('- [x] changed <!-- comet-task:a -->');
  });
  it('permits independent completion and idempotent retries without changing requirements', () => {
    const source = assignClassicTaskIds('- [ ] one\n- [ ] two\n');
    const revision = 'legacy-task-revision';
    const [one, two] = parseClassicTasks(source);
    const first = completeClassicTask(source, one.id!, revision);
    const second = completeClassicTask(first, two.id!, revision);
    expect(parseClassicTasks(second).every((task) => task.completed)).toBe(true);
    expect(completeClassicTask(second, one.id!, revision)).toBe(second);
    expect(classicTaskRequirements(second)).toBe(source);
  });
  it('rejects duplicate IDs, malformed IDs and ambiguous legacy completion', () => {
    expect(() =>
      parseClassicTasks('- [ ] one <!-- comet-task:a -->\n- [ ] two <!-- comet-task:a -->'),
    ).toThrow('Duplicate');
    expect(() => parseClassicTasks('- [ ] one <!-- comet-task: -->')).toThrow('Malformed');
    const legacy = '- [ ] one\n';
    expect(() => completeClassicTask(legacy, 'one', 'legacy-task-revision')).toThrow('Legacy');
  });
});

import { spawnSync } from 'child_process';
import { existsSync, promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { resolveClassicRunDirectory } from '../../../domains/comet-classic/classic-runtime-paths.js';
import { readRunState, writeRunState } from '../../../domains/engine/state.js';

const scriptsDir = path.resolve('assets', 'skills', 'comet', 'scripts');
const scriptByCommand: Record<string, string> = {
  guard: path.join(scriptsDir, 'comet-guard.mjs'),
  handoff: path.join(scriptsDir, 'comet-handoff.mjs'),
  state: path.join(scriptsDir, 'comet-state.mjs'),
};
const temporary: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporary
      .splice(0)
      .map((dir) => fs.rm(dir, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })),
  );
});

function run(cwd: string, ...args: string[]) {
  const [command, ...rest] = args;
  return spawnSync(process.execPath, [scriptByCommand[command as string], ...rest], {
    cwd,
    encoding: 'utf8',
  });
}

async function makeProject(): Promise<string> {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-handoff-'));
  temporary.push(dir);
  await fs.mkdir(path.join(dir, '.comet'), { recursive: true });
  await fs.writeFile(
    path.join(dir, '.comet', 'config.yaml'),
    [
      'schema: comet.project.v1',
      'default_workflow: classic',
      'workflows: [classic]',
      'classic:',
      '  artifact_layout: legacy',
      '',
    ].join('\n'),
  );
  await fs.mkdir(path.join(dir, 'openspec', 'changes'), { recursive: true });
  return dir;
}

async function seedDesignChange(dir: string, name = 'demo'): Promise<string> {
  run(dir, 'state', 'init', name, 'full', '--runtime', 'compat');
  const changeDir = path.join(dir, 'openspec', 'changes', name);
  // Open→design transition requires the open artifacts to exist first.
  await fs.writeFile(path.join(changeDir, 'proposal.md'), 'proposal\n');
  await fs.writeFile(path.join(changeDir, 'design.md'), 'design\n');
  await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement handoff\n');
  run(dir, 'state', 'transition', name, 'open-complete'); // open -> design (full workflow)
  return changeDir;
}

describe('Classic handoff command', () => {
  it('rejects a nested handoff junction without writing outside the project', async () => {
    const dir = await makeProject();
    const previous = process.cwd();
    process.chdir(dir);
    try {
      expect(
        (await runClassicCli(['state', 'init', 'linked-handoff', 'full', '--runtime', 'compat']))
          .exitCode,
      ).toBe(0);
      const changeDir = path.join(dir, 'openspec', 'changes', 'linked-handoff');
      await fs.writeFile(path.join(changeDir, 'proposal.md'), 'proposal\n');
      await fs.writeFile(path.join(changeDir, 'design.md'), 'design\n');
      await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement\n');
      expect(
        (await runClassicCli(['state', 'transition', 'linked-handoff', 'open-complete'])).exitCode,
      ).toBe(0);

      const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-handoff-outside-'));
      temporary.push(outside);
      await fs.writeFile(path.join(outside, 'marker.txt'), 'unchanged\n');
      await fs.symlink(
        outside,
        path.join(changeDir, '.comet', 'handoff'),
        process.platform === 'win32' ? 'junction' : 'dir',
      );

      const result = await runClassicCli([
        'handoff',
        'linked-handoff',
        'design',
        '--write',
        '--full',
      ]);

      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/symbolic link or junction/iu);
      expect(await fs.readFile(path.join(outside, 'marker.txt'), 'utf8')).toBe('unchanged\n');
      expect(await fs.readdir(outside)).toEqual(['marker.txt']);
    } finally {
      process.chdir(previous);
    }
  });

  it('references original requirements without generating a default handoff copy', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status, result.stderr).toBe(0);
    expect(result.stderr).toContain('[HANDOFF] source openspec/changes/demo/proposal.md');
    expect(existsSync(path.join(changeDir, '.comet/handoff'))).toBe(false);
    expect(run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim()).toBe(
      'openspec/changes/demo/proposal.md',
    );
    expect(run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim()).toBe('null');
    const state = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(state).toMatchObject({
      currentStep: 'full.design.document',
      iteration: 1,
      pending: null,
    });
    expect(
      await fs.readFile(
        path.join(await resolveClassicRunDirectory(changeDir), state!.contextRef),
        'utf8',
      ),
    ).toBe(await fs.readFile(path.join(changeDir, 'proposal.md'), 'utf8'));
    await expect(
      fs.access(path.join(await resolveClassicRunDirectory(changeDir), state!.pendingRef)),
    ).rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('generates one complete optional handoff view without advancing the original Run', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const before = await readRunState(await resolveClassicRunDirectory(changeDir));
    const spec = path.join(changeDir, 'specs', 'nested', 'worker', 'spec.md');
    await fs.mkdir(path.dirname(spec), { recursive: true });
    await fs.writeFile(spec, 'The complete nested worker requirement.\n');
    const result = run(dir, 'handoff', 'demo', 'design', '--write', '--full');
    expect(result.status, result.stderr).toBe(0);
    expect(await fs.readdir(path.join(changeDir, '.comet/handoff'))).toEqual(['design-context.md']);
    const view = await fs.readFile(
      path.join(changeDir, '.comet/handoff/design-context.md'),
      'utf8',
    );
    expect(view).toContain('The complete nested worker requirement.');
    expect(view).toContain('openspec/changes/demo/specs/nested/worker/spec.md');
    expect(view).not.toContain('sha256');
    expect(await readRunState(await resolveClassicRunDirectory(changeDir))).toEqual(before);
  });

  it('refreshes the design handoff from the build phase after a Spec Patch', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const beforeContext = run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim();
    const beforeText = await fs.readFile(path.join(dir, beforeContext), 'utf8');

    // Enter build through the real guard transition, not a forced phase write.
    // The full workflow requires a recorded Design Doc before leaving design.
    const designDoc = path.join(dir, 'docs', 'superpowers', 'specs', 'demo-design.md');
    await fs.mkdir(path.dirname(designDoc), { recursive: true });
    await fs.writeFile(
      designDoc,
      [
        '---',
        'comet_change: demo',
        'role: technical-design',
        'canonical_spec: openspec',
        '---',
        '',
        '# Design',
        '',
      ].join('\n'),
    );
    expect(
      run(dir, 'state', 'set', 'demo', 'design_doc', 'docs/superpowers/specs/demo-design.md')
        .status,
    ).toBe(0);
    const guard = run(dir, 'guard', 'demo', 'design', '--apply');
    expect(guard.status, guard.stderr).toBe(0);
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');
    const runStateBefore = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateBefore).not.toBeNull();
    expect(runStateBefore!.currentStep).toBe('full.build.configure');

    // Spec Patch the source evidence while in build.
    await fs.appendFile(path.join(changeDir, 'proposal.md'), 'build-phase change\n');

    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status, result.stderr).toBe(0);
    const afterContext = run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim();
    expect(await fs.readFile(path.join(dir, afterContext), 'utf8')).toContain('build-phase change');
    expect(await fs.readFile(path.join(dir, afterContext), 'utf8')).not.toBe(beforeText);
    expect(run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim()).toBe('null');

    // The refresh must not move the workflow phase or the Runtime currentStep.
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');
    const runStateAfter = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateAfter).not.toBeNull();
    expect(runStateAfter!.currentStep).toBe('full.build.configure');
  });

  it('reconciles a matching pending handoff and records recovery once', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const hash = run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim();
    const runStateBefore = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateBefore).not.toBeNull();
    const actionId = `classic-handoff:${hash}`;
    await fs.writeFile(
      path.join(await resolveClassicRunDirectory(changeDir), runStateBefore!.pendingRef),
      JSON.stringify({
        id: actionId,
        stepId: runStateBefore!.currentStep,
        type: 'handoff',
        ref: hash,
      }),
    );
    await writeRunState(await resolveClassicRunDirectory(changeDir), {
      ...runStateBefore!,
      pending: actionId,
    });

    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status).toBe(0);
    const afterRunState = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(afterRunState).not.toBeNull();
    expect(afterRunState!.pending).toBeNull();
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const trajectory = (
      await fs.readFile(
        path.join(await resolveClassicRunDirectory(changeDir), afterRunState!.trajectoryRef),
        'utf8',
      )
    )
      .trim()
      .split(/\r?\n/u)
      .map((line) => JSON.parse(line) as { type: string; data?: { kind?: string } });
    expect(
      trajectory.filter(
        (event) => event.type === 'recovery_reconciled' && event.data?.kind === 'classic-handoff',
      ),
    ).toHaveLength(1);
  });
});

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

describe.each(['skills-zh', 'skills'])('%s SDK flow handoffs', (root) => {
  const read = (ref: string) => fs.readFile(path.resolve('assets', root, ref), 'utf8');
  it('routes preset scope checks to the matching Runtime reference without repeating file-count authorization', async () => {
    const entry = await read('comet-classic/SKILL.md');
    const section = root === 'skills-zh' ? '预设范围复核' : 'Preset scope';
    expect(entry).toContain(
      `reference/sdk-methods.md#${section.toLowerCase().replaceAll(' ', '-')}`,
    );
    expect(await read('comet-classic/reference/sdk-methods.md')).toContain(`## ${section}`);
    expect(entry).toContain('rulings.md');
    expect(entry).toContain('reference/compat.md');
    expect(entry).not.toContain('文件数超过提示阈值时，展示');
    expect(entry).not.toContain('changed-file count exceeds the advisory threshold, present');
  });
  it('discloses Compat commands separately and retains SDK methods and approvals', async () => {
    for (const name of [
      'comet-design',
      'comet-build',
      'comet-verify',
      'comet-archive',
      'comet-hotfix',
      'comet-tweak',
    ]) {
      const main = await read(`${name}/SKILL.md`);
      expect(main).toContain('](reference/compat.md)');
      expect(main).toContain('../comet-classic/reference/sdk-methods.md');
      if (['comet-build', 'comet-verify'].includes(name)) expect(main).toContain('--checks');
      expect(main).not.toContain('comet state set <name>');
      const compat = await read(`${name}/reference/compat.md`);
      expect(compat).toContain('comet state select');
    }
    const methods = await read('comet-classic/reference/sdk-methods.md');
    for (const contract of [
      'configuration.language',
      'comet-task-authority',
      'base-ref',
      'CRITICAL/IMPORTANT',
      'platform-execution.md',
      'rulings.md',
      'complete-delivery',
    ])
      expect(methods).toContain(contract);
    for (const name of ['comet-hotfix', 'comet-tweak']) {
      const main = await read(`${name}/SKILL.md`);
      expect(main).toContain('open --json');
      expect(main).toContain('open --apply --approval-hash');
    }
  });
  it('submits checked Design, Verify, and Archive directly and supports explicit configuration approval', async () => {
    expect(await read('comet-design/SKILL.md')).not.toContain(
      '`comet guard <change-name> design --design-doc <design-doc-ref>`',
    );
    expect(await read('comet-verify/SKILL.md')).not.toContain(
      '`comet guard <change-name> verify --report <report-ref>`',
    );
    expect(await read('comet-archive/SKILL.md')).not.toContain(
      '`comet guard <change-name> archive`',
    );
    expect(await read('comet-build/SKILL.md')).toContain(
      'propose-build <change-name> --file <configuration-json> --confirmed',
    );
  });
  it('ships the complete edit-review protocol and distinguishes SDK Archive from Git delivery', async () => {
    const review = await read('comet/reference/edit-review.md');
    const required =
      root === 'skills-zh'
        ? [
            '当前 Agent 判断实际影响',
            '文件内容变化不自动撤回批准',
            '不提交文件指纹',
            '用户决定',
            '归档进度',
          ]
        : [
            'current Agent judges their effect',
            'do not automatically revoke approval',
            'Do not submit file fingerprints',
            'user decisions',
            'Archive progress',
          ];
    for (const term of required) expect(review).toContain(term);
    for (const obsolete of ['recordTemplate', 'prepare-applied --', 'edit-review record'])
      expect(review).not.toContain(obsolete);
    const native = await read('comet-native/SKILL.md');
    expect(native).toContain('reference/edit-review.md');
    expect(await read('comet-native/reference/edit-review.md')).toBe(review);
    expect(native).toContain('SDK');
    expect(native).toContain('Compat');
    const workspace = await read('comet-native/reference/workspace.md');
    expect(workspace).toContain('SDK');
    expect(workspace).toContain('SHA');
    expect(workspace).toContain('Compat');
  });
});

import { mkdtemp, mkdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
const roots: string[] = [];
afterEach(async () => {
  vi.unstubAllEnvs();
  await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
});
it('routes a legacy check invocation to platform work without executing it or claiming a pass', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'classic-platform-command-'));
  roots.push(root);
  const dataRoot = await mkdtemp(path.join(os.tmpdir(), 'classic-platform-userdata-'));
  roots.push(dataRoot);
  vi.stubEnv('COMET_DATA_DIR', dataRoot);
  const change = path.join(root, 'docs/openspec/changes/sample');
  await mkdir(change, { recursive: true });
  await mkdir(path.join(root, '.comet'));
  await writeFile(
    path.join(root, '.comet/config.yaml'),
    'schema: comet.project.v1\ndefault_workflow: classic\nnative:\n  artifact_root: docs\nclassic:\n  artifact_layout: docs\n',
  );
  const marker = path.join(root, 'must-not-exist');
  await writeFile(
    path.join(change, '.comet.yaml'),
    'workflow: tweak\nphase: build\narchived: false\n',
  );
  const result = await runClassicCli(
    [
      'check',
      'run',
      'sample',
      'build',
      '--json',
      '--',
      process.execPath,
      '-e',
      `require('node:fs').writeFileSync(${JSON.stringify(marker)},'executed')`,
    ],
    undefined,
    { projectRoot: root, invocationCwd: root },
  );
  expect(result.exitCode, result.stderr ?? result.stdout).toBe(0);
  const output = JSON.parse(result.stdout!);
  const data = output.data;
  expect(data.status).toBe('platform-execution-required');
  expect(data.checksExecuted).toBe(false);
  expect(data).not.toHaveProperty('passed');
  expect(data).not.toHaveProperty('receiptRef');
  await expect(stat(marker)).rejects.toMatchObject({ code: 'ENOENT' });
  expect(await readFile(path.join(change, '.comet.yaml'), 'utf8')).toContain('phase: build');
});
